  _inferBusinessStep(actionName) {
    if (!actionName)
      return "observing";
    const actionLower = actionName.toLowerCase();
    if (actionLower.includes("recevoir") || actionLower.includes("receive"))
      return "receiving";
    if (actionLower.includes("exp\xE9dier") || actionLower.includes("ship"))
      return "shipping";
    if (actionLower.includes("stocker") || actionLower.includes("store"))
      return "storing";
    if (actionLower.includes("transformer") || actionLower.includes("transform"))
      return "transforming";
    if (actionLower.includes("contr\xF4ler") || actionLower.includes("inspect"))
      return "inspecting";
    if (actionLower.includes("emballer") || actionLower.includes("pack"))
      return "packing";
    if (actionLower.includes("d\xE9baller") || actionLower.includes("unpack"))
      return "unpacking";
    return "observing";
  }
